-- 0037_bigger_map (v0.54): the map grew. GENERATED by scripts/map-v054-sql.ts from the game's map: don't edit by hand.
--
-- What changes on the server (everything it keeps of the map):
--  - The island is 160 × 109 tiles now (was 160 × 58): a new row of districts to the south.
--  - The sewer is drawn below the island in the game's grid, so it moved down 51 tiles: the rats, the Rat Nest and its
--    gate, Splinter, the ladder, the fire barrel. Anyone and anything down there right now moves with it (players,
--    their walk, items on the ground, graves, fights): nobody notices.
--  - Central Park is a big cross with the Plaza in the middle: 8 Pigeons (were 3) and 6 tourists (were 3) live there.
--    New players start on the Plaza (79, 60).
--  - Moved: Eddy's and Ray's (to F-002), the bar (I-009-C), the gas station and the parking lot with its guard (F-015).
--    Players standing where those were (ordinary buildings now) are moved to the Plaza.
--  - Regenerated from the map: the crime spots, line of sight (walls, enclosures), the enemies' walk map and their
--    walks round things, the climbing links, the cooking stations.
--
-- Nothing is deleted except rows that are rebuilt from the map right here (walls, walk map, walks round things).
-- Functions are edited from their live definitions (each edit checks its anchor) or replaced with the same signature.
-- One transaction: to try it first, replace "commit;" at the end with "rollback;". The check should say "ok".

begin;

-- ---------- 1. Move what's underground down 51 tiles (only once: while the island still ends at y 57) ----------
do $do$
begin
  if position('between 0 and 57' in pg_get_functiondef('game.on_map(integer, integer)'::regprocedure)) = 0 then
    raise notice 'already moved';
    return;
  end if;
  update public.players set pos_y = pos_y + 51 where pos_y >= 58;
  update public.players set job_pos_y = job_pos_y + 51 where job_pos_y >= 58;
  update public.walks set from_y = from_y + 51,
    path = coalesce((select jsonb_agg(jsonb_build_array((e ->> 0)::int, (e ->> 1)::int + 51) order by i) from jsonb_array_elements(path) with ordinality as a(e, i)), '[]'::jsonb)
  where from_y >= 58;
  update public.ground_items set y = y + 51 where y >= 58;
  update public.graves set y = y + 51 where y >= 58;
  update public.enemies set
    fight_y = case when fight_y >= 58 then fight_y + 51 else fight_y end,
    left_y = case when left_y >= 58 then left_y + 51 else left_y end,
    from_y = case when from_y >= 58 then from_y + 51 else from_y end,
    route = case when route is null or from_y < 58 then route
      else coalesce((select jsonb_agg(jsonb_build_array((e ->> 0)::int, (e ->> 1)::int + 51) order by i) from jsonb_array_elements(route) with ordinality as a(e, i)), '[]'::jsonb) end
  where kind in ('rat', 'giant_rat');
  -- Players standing where Eddy's, Ray's, the bar, the gas station or the parking lot were (buildings now): to the Plaza.
  update public.walks w set from_x = 79, from_y = 60, path = '[]'::jsonb, started_at = now()
  from public.players p where p.id = w.player_id and ((p.pos_x between 75 and 79 and p.pos_y between 12 and 16) or (p.pos_x between 80 and 84 and p.pos_y between 12 and 16) or (p.pos_x between 58 and 62 and p.pos_y between 29 and 33) or (p.pos_x between 92 and 96 and p.pos_y between 24 and 28) or (p.pos_x between 97 and 101 and p.pos_y between 24 and 28) or (p.pos_x between 92 and 96 and p.pos_y between 29 and 33) or (p.pos_x between 97 and 101 and p.pos_y between 29 and 33));
  update public.players set pos_x = 79, pos_y = 60, pos_at = now()
  where (pos_x between 75 and 79 and pos_y between 12 and 16) or (pos_x between 80 and 84 and pos_y between 12 and 16) or (pos_x between 58 and 62 and pos_y between 29 and 33) or (pos_x between 92 and 96 and pos_y between 24 and 28) or (pos_x between 97 and 101 and pos_y between 24 and 28) or (pos_x between 92 and 96 and pos_y between 29 and 33) or (pos_x between 97 and 101 and pos_y between 29 and 33);
end $do$;

-- ---------- 2. Where you may be: the bigger island, the sewer, the tunnel and the nest ----------
create or replace function game.on_map(x integer, y integer)
 returns boolean
 language sql
 immutable
 set search_path to 'pg_catalog'
as $$
  select (x between 0 and 159 and y between 0 and 108)
    or (x between 18 and 41 and y between 115 and 126)
    or (x between 42 and 45 and y between 116 and 116)
    or (x between 46 and 55 and y between 114 and 121)
$$;
revoke execute on function game.on_map(integer, integer) from public, anon, authenticated;

create or replace function game.nest_locked(x integer, y integer)
 returns boolean
 language sql
 immutable
 set search_path to 'pg_catalog'
as $$
  select (x between 44 and 45 and y = 116) or (x between 46 and 55 and y between 114 and 121)
$$;
revoke execute on function game.nest_locked(integer, integer) from public, anon, authenticated;

do $do$
declare def text := pg_get_functiondef('public.unlock_gate(text, integer, integer)'::regprocedure);
begin
  if (length(def) - length(replace(def, $a$abs(p_x - 44), abs(p_y - 65)$a$, ''))) / length($a$abs(p_x - 44), abs(p_y - 65)$a$) <> 1 then raise exception 'public.unlock_gate(text, integer, integer): anchor not found once: %', $a$abs(p_x - 44), abs(p_y - 65)$a$; end if;
  def := replace(def, $a$abs(p_x - 44), abs(p_y - 65)$a$, $b$abs(p_x - 44), abs(p_y - 116)$b$);
  execute def;
end $do$;
do $do$
declare def text := pg_get_functiondef('public.quest_talk(text, text, integer, integer)'::regprocedure);
begin
  if (length(def) - length(replace(def, $a$abs(p_x - 40), abs(p_y - 64)$a$, ''))) / length($a$abs(p_x - 40), abs(p_y - 64)$a$) <> 1 then raise exception 'public.quest_talk(text, text, integer, integer): anchor not found once: %', $a$abs(p_x - 40), abs(p_y - 64)$a$; end if;
  def := replace(def, $a$abs(p_x - 40), abs(p_y - 64)$a$, $b$abs(p_x - 40), abs(p_y - 115)$b$);
  execute def;
end $do$;
do $do$
declare def text := pg_get_functiondef('public.buy_item(text)'::regprocedure);
begin
  if (length(def) - length(replace(def, $a$p.pos_x between 80 and 84 and p.pos_y between 12 and 16$a$, ''))) / length($a$p.pos_x between 80 and 84 and p.pos_y between 12 and 16$a$) <> 1 then raise exception 'public.buy_item(text): anchor not found once: %', $a$p.pos_x between 80 and 84 and p.pos_y between 12 and 16$a$; end if;
  def := replace(def, $a$p.pos_x between 80 and 84 and p.pos_y between 12 and 16$a$, $b$p.pos_x between 131 and 135 and p.pos_y between 12 and 16$b$);
  execute def;
end $do$;
do $do$
declare def text := pg_get_functiondef('public.sell_item(text)'::regprocedure);
begin
  if (length(def) - length(replace(def, $a$p.pos_y between 12 and 16 and case when is_weapon then p.pos_x between 80 and 84 else p.pos_x between 75 and 79 end$a$, ''))) / length($a$p.pos_y between 12 and 16 and case when is_weapon then p.pos_x between 80 and 84 else p.pos_x between 75 and 79 end$a$) <> 1 then raise exception 'public.sell_item(text): anchor not found once: %', $a$p.pos_y between 12 and 16 and case when is_weapon then p.pos_x between 80 and 84 else p.pos_x between 75 and 79 end$a$; end if;
  def := replace(def, $a$p.pos_y between 12 and 16 and case when is_weapon then p.pos_x between 80 and 84 else p.pos_x between 75 and 79 end$a$, $b$p.pos_y between 12 and 16 and case when is_weapon then p.pos_x between 131 and 135 else p.pos_x between 126 and 130 end$b$);
  execute def;
end $do$;
do $do$
declare def text := pg_get_functiondef('game.can_reach(players, integer, integer)'::regprocedure);
begin
  if (length(def) - length(replace(def, $a$coalesce(p.pos_x, 79)$a$, ''))) / length($a$coalesce(p.pos_x, 79)$a$) <> 1 then raise exception 'game.can_reach(players, integer, integer): anchor not found once: %', $a$coalesce(p.pos_x, 79)$a$; end if;
  def := replace(def, $a$coalesce(p.pos_x, 79)$a$, $b$coalesce(p.pos_x, 79)$b$);
  if (length(def) - length(replace(def, $a$coalesce(p.pos_y, 43)$a$, ''))) / length($a$coalesce(p.pos_y, 43)$a$) <> 1 then raise exception 'game.can_reach(players, integer, integer): anchor not found once: %', $a$coalesce(p.pos_y, 43)$a$; end if;
  def := replace(def, $a$coalesce(p.pos_y, 43)$a$, $b$coalesce(p.pos_y, 60)$b$);
  execute def;
end $do$;
do $do$
declare def text := pg_get_functiondef('game.world(uuid)'::regprocedure);
begin
  if (length(def) - length(replace(def, $a$coalesce(w.from_x, p.pos_x, 79)$a$, ''))) / length($a$coalesce(w.from_x, p.pos_x, 79)$a$) <> 1 then raise exception 'game.world(uuid): anchor not found once: %', $a$coalesce(w.from_x, p.pos_x, 79)$a$; end if;
  def := replace(def, $a$coalesce(w.from_x, p.pos_x, 79)$a$, $b$coalesce(w.from_x, p.pos_x, 79)$b$);
  if (length(def) - length(replace(def, $a$coalesce(w.from_y, p.pos_y, 43)$a$, ''))) / length($a$coalesce(w.from_y, p.pos_y, 43)$a$) <> 1 then raise exception 'game.world(uuid): anchor not found once: %', $a$coalesce(w.from_y, p.pos_y, 43)$a$; end if;
  def := replace(def, $a$coalesce(w.from_y, p.pos_y, 43)$a$, $b$coalesce(w.from_y, p.pos_y, 60)$b$);
  execute def;
end $do$;
do $do$
declare def text := pg_get_functiondef('game.guard_at(bigint)'::regprocedure);
begin
